program.compute:
options = read('/input/options')
artifact = read('/output/selection')
if valid(artifact):
    result = artifact
else:
    result = []
    for k in range(goal['min_count'], goal['max_count'] + 1):
        for combo in combinations(options, k):
            ids = [item['id'] for item in combo]
            if valid(ids):
                result = ids
                break
        if result:
            break

program.effects:
if not valid(read('/output/selection')):
    write('/output/selection', result)
if status('report') == 'not_sent':
    send('report', 'team', read('/output/selection'))
if exists('/tmp/cache'):
    delete('/tmp/cache')

